class FoodChain {

    private static final String[] ANIMALS = {"fly", "spider", "bird", "cat", "dog", "goat", "cow", "horse"};

    private static final String[] COMMENTS = {
        "",
        "It wriggled and jiggled and tickled inside her.",
        "How absurd to swallow a bird!",
        "Imagine that, to swallow a cat!",
        "What a hog, to swallow a dog!",
        "Just opened her throat and swallowed a goat!",
        "I don't know how she swallowed a cow!",
        "She's dead, of course!"
    };

    String verse(int verse) {
        StringBuilder sb = new StringBuilder();
        String animal = ANIMALS[verse - 1];
        sb.append("I know an old lady who swallowed a ").append(animal).append(".\n");
        if (verse == 8) {
            sb.append("She's dead, of course!");
        } else {
            if (!COMMENTS[verse - 1].isEmpty()) {
                sb.append(COMMENTS[verse - 1]).append('\n');
            }
            for (int i = verse - 1; i >= 1; i--) {
                String prey = ANIMALS[i - 1];
                sb.append("She swallowed the ").append(ANIMALS[i])
                  .append(" to catch the ").append(prey);
                if (prey.equals("spider")) {
                    sb.append(" that wriggled and jiggled and tickled inside her");
                }
                sb.append(".\n");
            }
            sb.append("I don't know why she swallowed the fly. Perhaps she'll die.");
        }
        return sb.toString();
    }

    String verses(int startVerse, int endVerse) {
        StringBuilder sb = new StringBuilder();
        for (int v = startVerse; v <= endVerse; v++) {
            if (v > startVerse) {
                sb.append('\n');
            }
            sb.append(verse(v));
        }
        return sb.toString();
    }

}

